"""Goldens for the memory answers, generated by DeepEval from the fictional memory (never real data).

DeepEval's `deepeval generate` CLI needs a provider key; ours goes through the VisualContext server, so this is the
same generation from Python with that judge. Run from the repo root:  python evals/generate_dataset.py
"""
import json
from pathlib import Path

from deepeval.dataset import EvaluationDataset
from deepeval.synthesizer import Synthesizer
from deepeval.synthesizer.config import StylingConfig

import ai_app
from judge import JUDGE

HERE = Path(__file__).parent
# One context per day of memory, the way the phone would hand them to Gemini.
days: dict[str, list[str]] = {}
everything = ai_app.DATA
for e in everything["encounters"]:
    days.setdefault(e["at"][:10], []).append(" · ".join(x for x in [ai_app.fmt(e["at"]), "encontro com " + e["person_name"] if e.get("person_name") else "conversa com o assistente", e.get("place"), e["summary"]] if x))
for n in everything["notes"]:
    days.setdefault(n["at"][:10], []).append(f"nota {ai_app.fmt(n['at'])} · {n['title']}")
for t in everything["things"]:
    days.setdefault(t["seen_at"][:10], []).append(f"objeto {ai_app.fmt(t['seen_at'])} · {t['name']} em {t['location_description']}")
contexts = [v for _, v in sorted(days.items())]
(HERE / "data" / "contexts.json").write_text(json.dumps(contexts, ensure_ascii=False, indent=1))

synth = Synthesizer(model=JUDGE, styling_config=StylingConfig(
    scenario=f"Uma pessoa usando óculos inteligentes pergunta em voz alta sobre a própria memória (encontros, conversas, combinados, notas, onde deixou objetos). Hoje é {ai_app.fmt(everything['today'])} de 2026.",
    task="Responder pela memória pessoal: quem encontrou, onde, quando, o que combinou, o que anotou e onde deixou objetos, só com o que está nos registros.",
    input_format="Pergunta curta falada em português do Brasil, como 'o que eu fiz hoje?', 'quando vi o Bruno pela última vez?', 'o que combinei com a Ana?', 'onde deixei as chaves?'.",
    expected_output_format="Resposta falada em português, 1 a 3 frases, com nomes, lugares e horas concretos e datas resolvidas.",
))
synth.generate_goldens_from_contexts(contexts=contexts, max_goldens_per_context=5, include_expected_output=True)
ds = EvaluationDataset(goldens=synth.synthetic_goldens)
ds.save_as(file_type="json", directory=str(HERE), file_name=".dataset")
print(len(synth.synthetic_goldens), "goldens em evals/.dataset.json")
